import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";

const CATALOG_URL =
  "https://openrouter.ai/api/v1/models?output_modalities=all&sort=newest&offset=0&limit=1000";
const TARGET_PATH = path.resolve("client/src/data/models.ts");
const ARRAY_MARKER = "const rawCatalogModels: RawCatalogModel[] = ";
const BATCH_VARIANT_ARRAY_MARKER =
  "const rawBatchServingVariants: RawCatalogModel[] = ";
const UNCERTAIN_BLOCK_MARKER =
  "// Generated by scripts/update-openrouter-models.mjs.";
const UNCERTAIN_MARKER = "const uncertainCatalogModelIds = new Set<string>(";
const CURRENT_TIME_MARKER = "const CURRENT_TIME_SECONDS";
const ALLOWED_INPUT_MODALITIES = new Set([
  "text",
  "image",
  "audio",
  "video",
  "file",
]);
const BATCH_VARIANT_SUFFIX = ":batch";
const SPECIALIZED_CATALOG_MODEL_IDS = new Set([
  "bytedance-seed/seedream-5-0-pro",
  "bytedance/seedance-2.0-mini",
  "deepgram/flux-tts:free",
  "x-ai/grok-imagine-image-2.0",
]);

const AUTHOR_NAMES = new Map([
  ["anthropic", "Anthropic"],
  ["openai", "OpenAI"],
  ["moonshotai", "MoonshotAI"],
  ["google", "Google"],
  ["x-ai", "xAI"],
  ["qwen", "Qwen"],
  ["deepseek", "DeepSeek"],
  ["mistralai", "Mistral AI"],
  ["meta-llama", "Meta"],
  ["microsoft", "Microsoft"],
  ["nvidia", "NVIDIA"],
  ["minimax", "MiniMax"],
  ["openrouter", "OpenRouter"],
]);

function readInputPath() {
  const index = process.argv.indexOf("--input");
  return index >= 0 ? process.argv[index + 1] : "";
}

function providerSlug(modelId) {
  return String(modelId ?? "")
    .replace(/^~/, "")
    .split("/", 1)[0]
    .trim()
    .toLowerCase();
}

function fallbackAuthorName(slug) {
  return slug
    .split(/[-_]/g)
    .filter(Boolean)
    .map((part) => part[0]?.toUpperCase() + part.slice(1))
    .join(" ");
}

function parseExpirationDate(value) {
  if (value == null || value === "") return null;
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const parsed = Date.parse(String(value));
  return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : null;
}

function pricePerMillion(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed * 1_000_000 : 0;
}

function pricingOverrides(pricing) {
  if (!Array.isArray(pricing?.overrides)) return [];
  return pricing.overrides
    .filter(
      (override) =>
        override &&
        Number.isFinite(Number(override.min_prompt_tokens)) &&
        Number(override.min_prompt_tokens) >= 0,
    )
    .map((override) => ({
      min_prompt_tokens: Number(override.min_prompt_tokens),
      input: pricePerMillion(override.prompt),
      output: pricePerMillion(override.completion),
    }))
    .sort((left, right) => left.min_prompt_tokens - right.min_prompt_tokens);
}

function compactStoredModel(model) {
  const overrides = Array.isArray(model.pricing?.overrides)
    ? model.pricing.overrides
    : [];
  if (overrides.length) return model;
  const { overrides: _ignored, ...pricing } = model.pricing ?? {};
  return { ...model, pricing };
}

async function loadCatalog() {
  const inputPath = readInputPath();
  if (inputPath) {
    return JSON.parse(await fs.readFile(path.resolve(inputPath), "utf8"));
  }
  const response = await fetch(CATALOG_URL, {
    headers: { Accept: "application/json" },
  });
  if (!response.ok) {
    throw new Error(`OpenRouter catalog request failed: HTTP ${response.status}`);
  }
  return response.json();
}

function parseCatalogModels(source) {
  const start = source.indexOf(ARRAY_MARKER);
  const batchVariantArrayStart = source.indexOf(
    BATCH_VARIANT_ARRAY_MARKER,
    start,
  );
  const uncertainBlockStart = source.indexOf(UNCERTAIN_BLOCK_MARKER, start);
  const uncertainStart = source.indexOf(UNCERTAIN_MARKER, start);
  const currentTimeStart = source.indexOf(CURRENT_TIME_MARKER, start);
  const end =
    batchVariantArrayStart >= 0
      ? batchVariantArrayStart
      : uncertainBlockStart >= 0
      ? uncertainBlockStart
      : uncertainStart >= 0
        ? uncertainStart
        : currentTimeStart;
  if (start < 0 || end < 0) {
    throw new Error("Unable to locate rawCatalogModels in models.ts");
  }
  const rawJson = source
    .slice(start + ARRAY_MARKER.length, end)
    .replace(/;\s*$/, "");
  return JSON.parse(rawJson);
}

function parseExistingAuthors(...sources) {
  const authors = new Map();
  for (const source of sources) {
    for (const model of parseCatalogModels(source)) {
      const slug = providerSlug(model.id);
      if (slug && model.model_author && !authors.has(slug)) {
        authors.set(slug, model.model_author);
      }
    }
  }
  return authors;
}

function normalizeModel(model, existingAuthors) {
  const slug = providerSlug(model.id);
  const inputModalities = Array.isArray(model.architecture?.input_modalities)
    ? model.architecture.input_modalities
        .map((value) => String(value))
        .filter((value) => ALLOWED_INPUT_MODALITIES.has(value))
    : [];
  const outputModalities = Array.isArray(model.architecture?.output_modalities)
    ? model.architecture.output_modalities.map((value) => String(value))
    : [];
  const overrides = pricingOverrides(model.pricing);

  return {
    id: String(model.id),
    canonical_slug: String(model.canonical_slug || model.id),
    name: String(model.name || model.id),
    raw_description: String(model.description || ""),
    context_length: Math.max(0, Number(model.context_length) || 0),
    pricing: {
      input: pricePerMillion(model.pricing?.prompt),
      output: pricePerMillion(model.pricing?.completion),
      ...(overrides.length ? { overrides } : {}),
    },
    input_modalities: inputModalities,
    output_modalities: outputModalities,
    tokenizer: String(model.architecture?.tokenizer || "Other"),
    supported_parameters: Array.isArray(model.supported_parameters)
      ? model.supported_parameters.map((value) => String(value))
      : [],
    created: Math.max(0, Number(model.created) || 0),
    expiration_date: parseExpirationDate(model.expiration_date),
    model_author:
      AUTHOR_NAMES.get(slug) ||
      existingAuthors.get(slug) ||
      fallbackAuthorName(slug) ||
      "Unknown",
    ...(model.reasoning ? { reasoning_declared: true } : {}),
  };
}

async function main() {
  const source = await fs.readFile(TARGET_PATH, "utf8");
  const existingAuthors = parseExistingAuthors(source);
  const payload = await loadCatalog();
  if (!Array.isArray(payload.data)) {
    throw new Error("OpenRouter catalog response is missing data[]");
  }

  const currentModels = parseCatalogModels(source).map(compactStoredModel);
  const currentModelsById = new Map(
    currentModels.map((model) => [model.id, model]),
  );
  const catalogModels = payload.data
    .filter((model) => model && typeof model.id === "string")
    .map((model) => normalizeModel(model, existingAuthors));
  const liveModels = catalogModels.filter(
    (model) => !model.id.endsWith(BATCH_VARIANT_SUFFIX),
  );
  const batchServingVariants = catalogModels
    .filter((model) => model.id.endsWith(BATCH_VARIANT_SUFFIX))
    .sort(
      (left, right) =>
        right.created - left.created || left.id.localeCompare(right.id),
    );
  const retainedModels = currentModels;
  const liveModelIds = new Set(liveModels.map((model) => model.id));
  const mergedById = new Map(retainedModels.map((model) => [model.id, model]));
  for (const model of liveModels) {
    const specializedModel = currentModelsById.get(model.id);
    mergedById.set(
      model.id,
      SPECIALIZED_CATALOG_MODEL_IDS.has(model.id) && specializedModel
        ? specializedModel
        : model,
    );
  }
  const normalized = [...mergedById.values()]
    .sort(
      (left, right) =>
        right.created - left.created || left.id.localeCompare(right.id),
    );
  const nowSeconds = Math.floor(Date.now() / 1000);
  const uncertainModelIds = normalized
    .filter(
      (model) =>
        !liveModelIds.has(model.id) &&
        !(
          model.expiration_date !== null &&
          model.expiration_date <= nowSeconds
        ),
    )
    .map((model) => model.id)
    .sort((left, right) => left.localeCompare(right));

  const start = source.indexOf(ARRAY_MARKER);
  const currentTimeStart = source.indexOf(CURRENT_TIME_MARKER, start);
  if (start < 0 || currentTimeStart < 0) {
    throw new Error("Unable to locate generated model catalog boundaries");
  }
  const generatedAt = new Date().toISOString();
  const newestPublishedAt = new Date(
    Math.max(0, ...liveModels.map((model) => model.created)) * 1000,
  ).toISOString();
  const header = source
    .slice(0, start)
    .replace(
      /\/\/ (?:Generated|Merged with OpenRouter model catalog on)[^\r\n]*/,
      `// Merged with OpenRouter model catalog on ${generatedAt}.`,
    )
    .replace(
      /\/\/ Refreshed with entries published through[^\r\n]*/,
      `// Refreshed with entries published through ${newestPublishedAt}.`,
    )
    .replace(/\/\/ Source:[^\r\n]*/, `// Source: ${CATALOG_URL}`);
  const nextSource =
    header +
    ARRAY_MARKER +
    JSON.stringify(normalized, null, 2) +
    ";\n\n" +
    BATCH_VARIANT_ARRAY_MARKER +
    JSON.stringify(batchServingVariants, null, 2) +
    ";\n\n" +
    "// Generated by scripts/update-openrouter-models.mjs. Entries remain callable\n" +
    "// but carry a warning because they are absent from the current live catalog.\n" +
    UNCERTAIN_MARKER +
    JSON.stringify(uncertainModelIds, null, 2) +
    ");\n\n" +
    source.slice(currentTimeStart);

  await fs.writeFile(TARGET_PATH, nextSource, "utf8");
  process.stdout.write(
    `Updated ${path.relative(process.cwd(), TARGET_PATH)} with ${normalized.length} snapshot models (${liveModels.length} live, ${uncertainModelIds.length} uncertain) and ${batchServingVariants.length} uncounted batch serving variants.\n`,
  );
}

await main();
